from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import pytest

app = FastAPI()
counter = 0

def dep():
    global counter
    counter += 1
    return counter

@app.get("/", dependencies=[Depends(dep, scope="function")])
def read_root():
    return {"counter": counter}

client = TestClient(app)

def test_function_scope_dependency():
    global counter
    counter = 0
    # First call
    response = client.get("/")
    assert response.json() == {"counter": 1}
    # Second call
    response = client.get("/")
    assert response.json() == {"counter": 2}

def test_request_scope_dependency():
    global counter
    counter = 0
    app_request = FastAPI()

    @app_request.get("/", dependencies=[Depends(dep, scope="request")])
    def read_root_request():
        return {"counter": counter}

    client_request = TestClient(app_request)

    # First call
    response = client_request.get("/")
    assert response.json() == {"counter": 1}
    # Second call (new request, so it should be called again)
    response = client_request.get("/")
    assert response.json() == {"counter": 2}

if __name__ == "__main__":
    test_function_scope_dependency()
    test_request_scope_dependency()
    print("Tests passed!")

